def solution(records, limit):
    times = {}
    flagged = set()
    for rec in records:
        hms, user, amount = rec.split()
        amount = int(amount)
        if amount == 0:
            continue
        if amount >= limit:
            flagged.add(user)
        h, m, s = map(int, hms.split(':'))
        times.setdefault(user, []).append(h * 3600 + m * 60 + s)
    for user, ts in times.items():
        if user in flagged:
            continue
        ts.sort()
        for i in range(len(ts) - 2):
            if ts[i + 2] - ts[i] < 60:
                flagged.add(user)
                break
    return sorted(flagged)
